package com.pulsepay.developer;
import com.pulsepay.common.ApiException; import com.pulsepay.security.MerchantPrincipal; import com.pulsepay.webhook.SecretCrypto; import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class DeveloperController {
 private final JdbcTemplate db; private final SecretCrypto crypto; public DeveloperController(JdbcTemplate db,SecretCrypto crypto){this.db=db;this.crypto=crypto;} record KeyRequest(String name){} record WebhookRequest(String url,List<String> eventTypes){} record WebhookUpdateRequest(String url,List<String> eventTypes,Boolean enabled){}
 @PostMapping("/api-keys") @Transactional @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> key(@AuthenticationPrincipal MerchantPrincipal p,@RequestBody KeyRequest r){String secret="pp_test_"+UUID.randomUUID().toString().replace("-","");UUID id=UUID.randomUUID();String pub="key_"+id.toString().replace("-","");db.update("insert into api_keys(id,merchant_id,public_id,name,secret_hash)values(?,?,?,?,?)",id,p.merchantId(),pub,r.name()==null?"Default key":r.name(),sha(secret));audit(p,"api_key.created","api_key",id);return Map.of("id",pub,"secret",secret,"message","Store this secret now; it will not be displayed again.");}
 @GetMapping("/api-keys") public List<Map<String,Object>> keys(@AuthenticationPrincipal MerchantPrincipal p){return db.query("select public_id,name,test_mode,created_at,last_used_at,revoked_at from api_keys where merchant_id=? order by created_at desc",(rs,i)->Map.of("id",rs.getString(1),"name",rs.getString(2),"test_mode",rs.getBoolean(3),"created_at",rs.getTimestamp(4).toInstant().toString(),"revoked",rs.getTimestamp(6)!=null),p.merchantId());}
 @PostMapping("/api-keys/{id}/revoke") @Transactional public Map<String,Object> revokeKey(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String id){int changed=db.update("update api_keys set revoked_at=now() where merchant_id=? and public_id=? and revoked_at is null",p.merchantId(),id);if(changed==0)throw new ApiException(HttpStatus.NOT_FOUND,"API_KEY_NOT_FOUND","Active API key was not found.");audit(p,"api_key.revoked","api_key",UUID.nameUUIDFromBytes(id.getBytes(StandardCharsets.UTF_8)));return Map.of("id",id,"revoked",true);}
 @PostMapping("/api-keys/{id}/rotate") @Transactional public Map<String,Object> rotateKey(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String id){var names=db.query("select name from api_keys where merchant_id=? and public_id=? and revoked_at is null for update",(rs,i)->rs.getString(1),p.merchantId(),id);if(names.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"API_KEY_NOT_FOUND","Active API key was not found.");db.update("update api_keys set revoked_at=now() where merchant_id=? and public_id=?",p.merchantId(),id);String secret="pp_test_"+UUID.randomUUID().toString().replace("-","");UUID keyId=UUID.randomUUID();String publicId="key_"+keyId.toString().replace("-","");db.update("insert into api_keys(id,merchant_id,public_id,name,secret_hash)values(?,?,?,?,?)",keyId,p.merchantId(),publicId,names.getFirst(),sha(secret));audit(p,"api_key.rotated","api_key",keyId);return Map.of("id",publicId,"secret",secret,"replaces",id,"message","Store this replacement secret now; it will not be displayed again.");}
 @PostMapping("/webhooks") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> webhook(@AuthenticationPrincipal MerchantPrincipal p,@RequestBody WebhookRequest r){if(r.url()==null)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_WEBHOOK_URL","Webhook URLs must use HTTPS.");String url;try{url=com.pulsepay.webhook.WebhookUrlValidator.publicHttpsUri(r.url()).toString();}catch(IllegalArgumentException e){throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_WEBHOOK_URL",e.getMessage());}UUID id=UUID.randomUUID();String secret="whsec_"+UUID.randomUUID().toString().replace("-","");db.update("insert into webhook_endpoints(id,merchant_id,url,secret_hash,secret_encrypted,event_types)values(?,?,?,?,?,cast(? as jsonb))",id,p.merchantId(),url,sha(secret),crypto.encrypt(secret),json(r.eventTypes()));audit(p,"webhook.created","webhook_endpoint",id);return Map.of("id",id,"url",url,"secret",secret,"message","Store this signing secret now; it will not be displayed again.");}
 @GetMapping("/webhooks") public List<Map<String,Object>> webhooks(@AuthenticationPrincipal MerchantPrincipal p){return db.query("select id,url,event_types,enabled,created_at from webhook_endpoints where merchant_id=?",(rs,i)->Map.of("id",rs.getObject(1).toString(),"url",rs.getString(2),"events",rs.getString(3),"enabled",rs.getBoolean(4),"created_at",rs.getTimestamp(5).toInstant().toString()),p.merchantId());}
 @GetMapping("/webhook-events") public List<Map<String,Object>> webhookEvents(@AuthenticationPrincipal MerchantPrincipal p){return db.query("select id,event_type,payload,occurred_at from webhook_events where merchant_id=? order by occurred_at desc limit 100",(rs,i)->Map.of("id",rs.getObject(1).toString(),"event_type",rs.getString(2),"payload",rs.getString(3),"occurred_at",rs.getTimestamp(4).toInstant().toString()),p.merchantId());}
 @PatchMapping("/webhooks/{id}") @Transactional public Map<String,Object> updateWebhook(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable UUID id,@RequestBody WebhookUpdateRequest r){String url=null;if(r.url()!=null)try{url=com.pulsepay.webhook.WebhookUrlValidator.publicHttpsUri(r.url()).toString();}catch(IllegalArgumentException e){throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_WEBHOOK_URL",e.getMessage());}int changed=db.update("update webhook_endpoints set url=coalesce(?,url),enabled=coalesce(?,enabled),event_types=case when ? then cast(? as jsonb) else event_types end,updated_at=now() where merchant_id=? and id=?",url,r.enabled(),r.eventTypes()!=null,json(r.eventTypes()),p.merchantId(),id);if(changed==0)throw new ApiException(HttpStatus.NOT_FOUND,"WEBHOOK_NOT_FOUND","Webhook endpoint was not found.");audit(p,"webhook.updated","webhook_endpoint",id);return db.queryForObject("select id,url,event_types,enabled from webhook_endpoints where merchant_id=? and id=?",(rs,i)->Map.of("id",rs.getObject(1).toString(),"url",rs.getString(2),"events",rs.getString(3),"enabled",rs.getBoolean(4)),p.merchantId(),id);}
 @PostMapping("/webhooks/{id}/rotate-secret") @Transactional public Map<String,Object> rotateWebhookSecret(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable UUID id){String secret="whsec_"+UUID.randomUUID().toString().replace("-","");int changed=db.update("update webhook_endpoints set secret_hash=?,secret_encrypted=?,updated_at=now() where merchant_id=? and id=?",sha(secret),crypto.encrypt(secret),p.merchantId(),id);if(changed==0)throw new ApiException(HttpStatus.NOT_FOUND,"WEBHOOK_NOT_FOUND","Webhook endpoint was not found.");audit(p,"webhook.secret_rotated","webhook_endpoint",id);return Map.of("id",id,"secret",secret,"message","Store this signing secret now; it will not be displayed again.");}
 @GetMapping("/webhooks/{id}/deliveries") public List<Map<String,Object>> deliveries(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable UUID id){return db.query("select d.id,d.event_type,d.status,d.attempts,d.last_http_status,d.created_at from webhook_deliveries d join webhook_endpoints w on w.id=d.webhook_endpoint_id where w.merchant_id=? and w.id=? order by d.created_at desc",(rs,i)->Map.of("id",rs.getString(1),"event_type",rs.getString(2),"status",rs.getString(3),"attempts",rs.getInt(4),"http_status",rs.getObject(5)==null?"":rs.getInt(5),"created_at",rs.getTimestamp(6).toInstant().toString()),p.merchantId(),id);}
 @PostMapping("/webhooks/deliveries/{deliveryId}/retry") @Transactional public Map<String,Object> retryDelivery(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable UUID deliveryId){int changed=db.update("update webhook_deliveries d set status='PENDING',next_attempt_at=now(),updated_at=now() from webhook_endpoints w where d.webhook_endpoint_id=w.id and w.merchant_id=? and d.id=? and d.status in ('DEAD_LETTER','RETRYING')",p.merchantId(),deliveryId);if(changed==0)throw new ApiException(HttpStatus.NOT_FOUND,"WEBHOOK_DELIVERY_NOT_FOUND","Webhook delivery was not found or cannot be retried.");audit(p,"webhook.delivery_retried","webhook_delivery",deliveryId);return Map.of("id",deliveryId,"status","PENDING");}
 private void audit(MerchantPrincipal p,String action,String type,UUID id){db.update("insert into audit_logs(merchant_id,actor_user_id,action,resource_type,resource_id)values(?,?,?,?,?)",p.merchantId(),p.userId(),action,type,id);} private String sha(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} private String json(Object x){try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(x==null?List.of():x);}catch(Exception e){throw new IllegalArgumentException(e);}}
}
